{
  "userQuery": "上次那张卡片背景太素了，重新做一张低电卡片，背景要那种像夜空延伸出来的感觉。左边信息区显示日历日程和电量状态，电量低了橙色警告。右边动作区横向排几个可勾选的小卡片，勾完跳到系统设置里的省电、屏幕、电池优化这些。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    },
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "smart_charge_battery_health"
      }
    }
  ],
  "dataModel": {
    "value": {
      "card": {
        "title": "低电预警",
        "calendarLine": "19:30 视频会议",
        "batteryLine": "电量 18%",
        "warningText": "橙色警告",
        "actions": [
          {
            "label": "省电",
            "checked": false
          },
          {
            "label": "屏幕",
            "checked": false
          },
          {
            "label": "优化",
            "checked": false
          }
        ]
      },
      "data": {
        "calendar": {
          "items": []
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "power_warning_icon",
      "src": "assets/icons/power-warning.png",
      "use": "warning icon",
      "description": "橙色低电警告图标，适合用于低电状态的小型提示符号。",
      "static": true
    }
  ]
}

